import type { SVGProps } from 'react';

/*
 * Faithful ports of the current app's nav icons
 *   client/packages/common/src/ui/icons/*
 * from MUI SvgIcon to plain SVG (no MUI dependency).
 *
 * Convention preserved from the originals:
 *  - "fill" icons paint with `currentColor` (default svg fill).
 *  - "stroke" icons set fill:none and stroke:currentColor.
 * Either way, colour follows CSS `color`, and size follows font-size (1em),
 * exactly like the MUI SvgIcons they replace.
 */

export type IconProps = SVGProps<SVGSVGElement>;

const Fill = ({
  viewBox,
  children,
  ...props
}: IconProps & { viewBox: string }) => (
  <svg
    width="1em"
    height="1em"
    viewBox={viewBox}
    fill="currentColor"
    focusable="false"
    aria-hidden="true"
    {...props}
  >
    {children}
  </svg>
);

const Stroke = ({
  viewBox,
  strokeWidth = 2,
  children,
  ...props
}: IconProps & { viewBox: string }) => (
  <svg
    width="1em"
    height="1em"
    viewBox={viewBox}
    fill="none"
    stroke="currentColor"
    strokeWidth={strokeWidth}
    strokeLinecap="round"
    strokeLinejoin="round"
    focusable="false"
    aria-hidden="true"
    {...props}
  >
    {children}
  </svg>
);

